<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Simple Game</title>
    <style>
        body { margin: 0; }
        canvas { display: block; }
        #hud { position: absolute; top: 10px; left: 10px; color: white; font-family: Arial, sans-serif; }
    </style>
</head>
<body>
    <canvas id="gameCanvas" width="800" height="600"></canvas>
    <div id="hud">Score: 0</div>

    <script>
        const canvas = document.getElementById('gameCanvas');
        const ctx = canvas.getContext('2d');

        // Game variables
        let x = 50, y = 50, dx = 2, dy = 2;
        let score = 0;
        let level = 1;
        const levels = [
            { width: 800, height: 600, collectibles: [{x: 200, y: 300}], hazards: [], exit: {x: 750, y: 550} },
            // Add more levels as needed
        ];

        function draw() {
            ctx.clearRect(0, 0, canvas.width, canvas.height);

            // Draw player
            ctx.fillStyle = 'blue';
            ctx.fillRect(x, y, 20, 20);

            // Draw HUD
            document.getElementById('hud').innerText = `Score: ${score} Level: ${level}`;

            // Draw collectibles and hazards (simplified example)
            levels[level - 1].collectibles.forEach(collectible => {
                ctx.fillStyle = 'green';
                ctx.fillRect(collectible.x, collectible.y, 20, 20);
            });

            levels[level - 1].hazards.forEach(hazard => {
                ctx.fillStyle = 'red';
                ctx.fillRect(hazard.x, hazard.y, 20, 20);
            });

            // Check for collisions (simplified example)
            if (x > canvas.width - 20 || x < 0) dx = -dx;
            if (y > canvas.height - 20 || y < 0) dy = -dy;

            levels[level - 1].collectibles.forEach((collectible, index) => {
                if (Math.abs(x - collectible.x) < 20 && Math.abs(y - collectible.y) < 20) {
                    score++;
                    levels[level - 1].collectibles.splice(index, 1);
                }
            });

            // Check for exit
            if (x > levels[level - 1].exit.x - 20 && x < levels[level - 1].exit.x + 20 &&
                y > levels[level - 1].exit.y - 20 && y < levels[level - 1].exit.y + 20) {
                level++;
                if (level <= levels.length) {
                    // Reset player position
                    x = 50;
                    y = 50;
                } else {
                    alert('You win!');
                    document.location.reload();
                }
            }

            requestAnimationFrame(draw);
        }

        function move(event) {
            switch(event.key) {
                case 'ArrowUp':
                    dy = -2;
                    dx = 0;
                    break;
                case 'ArrowDown':
                    dy = 2;
                    dx = 0;
                    break;
                case 'ArrowLeft':
                    dx = -2;
                    dy = 0;
                    break;
                case 'ArrowRight':
                    dx = 2;
                    dy = 0;
                    break;
            }
        }

        document.addEventListener('keydown', move);
        draw();
    </script>
</body>
</html>
